  ('4abdb663-0707-40c6-bc81-ec7ff71ff442', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अंग्रेजों के खिलाफ़ उसके दिल में किस कदर नफ़रत है। कोई पाँच महीने हुकूमत की होगी। मगर इस पाँच महीने में वो अवध के दरबार को अंग्रेज़ी असर से बिलकुल पाक कर देने में तकरीबन कामयाब हो गया था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('eeb3525f-ae79-4adc-8412-157d62961ccb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल कॉलिंज ये सआदत अली कौन है? आसिफ़उद्दौला का भाई है। वज़ीर अली का और उसका दुश्मन।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6f3a1202-d9cc-4801-a5f3-53c8aa5f27a1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$असल में नवाब आसिफ़उद्दौला के यहाँ लड़के की कोई उम्मीद नहीं थी। वज़ीर अली की पैदाइश को सआदत अली ने अपनी मौत ख्याल किया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ba8db77c-6ec9-47fd-80b1-d5e914335fd4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मगर सआदत अली को अवध के तख़्त पर बिठाने में क्या मसलेहत थी? सआदत अली हमारा दोस्त है और बहुत ऐश पसंद आदमी है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bbe75e17-592e-4f6b-8800-8a813a48261d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसलिए हमें अपनी आधी मुमलिकत (जायदाद, दौलत) दे दी और दस लाख रुपये नकद। अब वो भी मज़े करता है और हम भी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
