  ('243eaadf-28a6-4293-8a29-f959ad2b3a38', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जंगल की जिंदगी बड़ी खतरनाक होती है। हफ़्तों हो गए यहाँ खेमा डाले हुए। सिपाही भी तंग आ गए हैं। ये वज़ीर अली आदमी है या भूत, हाथ ही नहीं लगता। उसके अफ़साने सुन के रॉबिनहुड के कारनामे याद आ जाते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1070dd21-9b8e-4764-8470-959f1fcbac3f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अंग्रेजों के खिलाफ़ उसके दिल में किस कदर नफ़रत है। कोई पाँच महीने हुकूमत की होगी। मगर इस पाँच महीने में वो अवध के दरबार को अंग्रेज़ी असर से बिलकुल पाक कर देने में तकरीबन कामयाब हो गया था। लेफ्टिनेंट: कर्नल कॉलिंज ये सआदत अली कौन है?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('801d46af-4bc6-4491-a555-f7296b600729', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$असल में नवाब आसिफ़उद्दौला के यहाँ लड़के की कोई उम्मीद नहीं थी। वज़ीर अली की पैदाइश को सआदत अली ने अपनी मौत ख्याल किया। मगर सआदत अली को अवध के तख़्त पर बिठाने में क्या मसलेहत थी? सआदत अली हमारा दोस्त है और बहुत ऐश पसंद आदमी है इसलिए हमें अपनी आधी मुमलिकत (जायदाद, दौलत) दे दी और दस लाख रुपये नकद। अब वो भी मज़े करता है और हम भी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d72b950d-8878-425d-ad22-d4212944c201', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ्टिनेंट: सुना है ये वज़ीर अली अफ़ग़ानिस्तान के बादशाह शाह-ए-ज़मा को हिंदुस्तान पर हमला करने की दावत (आमंत्रण) दे रहा है।
कर्नल: अफ़ग़ानिस्तान को हमले की दावत सबसे पहले असल में टीपू सुल्तान ने दी फिर वज़ीर अली ने भी उसे दिल्ली बुलाया और फिर शम्सुद्दौला ने भी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a216b7b9-48c3-4093-836f-46be002d6035', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ्टिनेंट: कौन शम्सुद्दौला?
कर्नल: नवाब बंगाल का निस्बती (रिश्ते) भाई। बहुत ही खतरनाक आदमी है।
लेफ्टिनेंट: इसका तो मतलब ये हुआ कि कंपनी के खिलाफ सारे हिंदुस्तान में एक लहर दौड़ गई है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('bad60ee8-2dff-4ca5-a4eb-9198d9f84cd0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: जी हाँ, और अगर ये कामयाब हो गई तो बक्सर और प्लासी के कारनामे धरे रह जाएँगे और कंपनी जो कुछ लॉर्ड क्लाइव के हाथों हासिल कर चुकी है, लॉर्ड वेलेज़ली के हाथों सब खो बैठेगी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('37c487f3-0849-42ec-aed6-f9c7af66d4ae', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ्टिनेंट: वज़ीर अली की आज़ादी बहुत खतरनाक है। हमें किसी न किसी तरह इस शख्स को गिरफ्तार कर ही लेना चाहिए।
कर्नल: पूरी एक फ़ौज लिए उसका पीछा कर रहा हूँ और बरसों से वो हमारी आँखों में धूल झोंक रहा है और इन्हीं जंगलों में फिर रहा है और हाथ नहीं आता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('86e9fbe1-3b7c-446a-92d0-690fc479c2c7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: उसके साथ चंद जाँबाज़ हैं। मुट्ठी भर आदमी मगर ये दमख़म है।
लेफ्टिनेंट: सुना है वज़ीर अली ज़ाती तौर से भी बहुत बहादुर आदमी है।
कर्नल: बहादुर न होता तो यूँ कंपनी के वकील को कत्ल कर देता?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('680bd0ec-ace5-462c-9f7a-22ad111449c5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ्टिनेंट: ये कत्ल का क्या किस्सा हुआ था कर्नल?
कर्नल: किस्सा क्या हुआ था उसको उसके पद से हटाने के बाद हमने वज़ीर अली को बनारस पहुँचा दिया और तीन लाख रुपया सालाना वज़ीफ़ा मुकर्रर कर दिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1634483b-100f-4dd7-b624-57718e99c4ea', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: कुछ महीने बाद गवर्नर जनरल ने उसे कलकत्ता (कोलकाता) तलब किया। वज़ीर अली कंपनी के वकील के पास गया जो बनारस में रहता था और उससे शिकायत की कि गवर्नर जनरल उसे कलकत्ता में क्यों तलब करता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('4dc619b9-1b37-40ba-82b6-d2873f026efe', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: वकील ने शिकायत की परवाह नहीं की उलटा उसे बुरा-भला सुना दिया। वज़ीर अली के तो दिल में यूँ भी अंग्रेज़ों के खिलाफ नफ़रत कूट-कूटकर भरी है उसने खंजर से वकील का काम तमाम कर दिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('05de91d4-452a-4d8b-b00b-a32bb66dbd22', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ्टिनेंट: और भाग गया?
कर्नल: अपने जानिसारों समेत आज़मगढ़ की तरफ भाग गया। आज़मगढ़ के हुक्मरान ने उन लोगों को अपनी हिफ़ाज़त में घाघरा तक पहुँचा दिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('90bce6a1-60ce-47d1-8143-2313e093429f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: अब ये कारवाँ इन जंगलों में कई साल से भटक रहा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('15288e80-eb2f-44b1-8fa1-22e5933b61fa', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ्टिनेंट: सुना है ये वज़ीर अली अफ़ग़ानिस्तान के बादशाह शाह-ए-ज़मा को हिंदुस्तान पर हमला करने की दावत (आमंत्रण) दे रहा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('14a0d169-a9b5-4a9c-bcb0-aee567507bca', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: अफ़ग़ानिस्तान को हमले की दावत सबसे पहले असल में टीपू सुल्तान ने दी फिर वज़ीर अली ने भी उसे दिल्ली बुलाया और फिर शम्सुद्दौला ने भी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0667b716-7c27-464c-a217-ad1c6c13633f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: नवाब बंगाल का निस्बती (रिश्ते) भाई। बहुत ही खतरनाक आदमी है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('8ca920d8-86a6-4a57-a9ff-ffb3f0ab15a4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ्टिनेंट: इसका तो मतलब ये हुआ कि कंपनी के खिलाफ सारे हिंदुस्तान में एक लहर दौड़ गई है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('30520c61-33ec-4295-84a4-d44c50fd1746', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: जी हाँ, और अगर ये कामयाब हो गई तो बक्सर और प्लासी के कारनामे धरे रह जाएँगे और कंपनी जो कुछ लॉर्ड क्लाइव के हाथों हासिल कर चुकी है, लॉर्ड वेलेज़ली के हाथों सब खो बैठेगी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('fd702640-26d9-4b8c-90eb-ac88b5a04b0d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ्टिनेंट: वज़ीर अली की आज़ादी बहुत खतरनाक है। हमें किसी न किसी तरह इस शख्स को गिरफ्तार कर ही लेना चाहिए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('75e42ba8-350c-4478-8c5f-6b574970e861', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: पूरी एक फ़ौज लिए उसका पीछा कर रहा हूँ और बरसों से वो हमारी आँखों में धूल झोंक रहा है और इन्हीं जंगलों में फिर रहा है और हाथ नहीं आता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('63928405-6dda-49d9-9089-d9b5ca818dd6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: उसके साथ चंद जाँबाज़ हैं। मुट्ठी भर आदमी मगर ये दमख़म है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e6e84a8d-93b9-4dc7-bfbd-2db503bb4675', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: किस्सा क्या हुआ था उसको उसके पद से हटाने के बाद हमने वज़ीर अली को बनारस पहुँचा दिया और तीन लाख रुपया सालाना वज़ीफ़ा मुकर्रर कर दिया। कुछ महीने बाद गवर्नर जनरल ने उसे कलकत्ता (कोलकाता) तलब किया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('a242af9c-1676-488d-a8fe-e6c12231c84f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल: वज़ीर अली कंपनी के वकील के पास गया जो बनारस में रहता था और उससे शिकायत की कि गवर्नर जनरल उसे कलकत्ता में क्यों तलब करता है। वकील ने शिकायत की परवाह नहीं की उलटा उसे बुरा-भला सुना दिया। वज़ीर अली के तो दिल में यूँ भी अंग्रेज़ों के खिलाफ नफ़रत कूट-कूटकर भरी है उसने खंजर से वकील का काम तमाम कर दिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('2dc8a545-f46e-4e82-b52e-9b2dc77c3847', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ़्टिनेंट µ मगर वज़ीर अली की स्कीम क्या है? कर्नल µ स्कीम ये है कि किसी तरह नेपाल पहुँच जाए। अफ़ग़ानी हमले का इंतज़ार करे, अपनी ताक़त बढ़ाए, सआदत अली को उसके पद से हटाकर ख़ुद अवध पर कब्ज़ा करे और अंग्रेज़ों को हिंदुस्तान से निकाल दे। लेफ़्टिनेंट µ नेपाल पहुँचना तो कोई ऐसा मुश्किल नहीं, मुमकिन है कि पहुँच गया हो। कर्नल µ हमारी फ़ौजें और नवाब सआदत अली ख़ाँ के सिपाही बड़ी सख़्ती से उसका पीछा कर रहे हैं। हमें अच्छी तरह मालूम है कि वो इन्हीं जंगलों में है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('021167f5-03f9-49c7-bc45-66a223af708f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$(एक सिपाही तेज़ी से दाख़िल होता है) कर्नल µ (उठकर) क्या बात है? गोरा µ दूर से गर्द उठती दिखाई दे रही है। कर्नल µ सिपाहियों से कह दो कि तैयार रहें (सिपाही सलाम करके चला जाता है) लेफ़्टिनेंट µ (जो खिड़की से बाहर देखने में मसरूफ़ था) गर्द तो ऐसी उड़ रही है जैसे कि पूरा एक काफ़िला चला आ रहा हो मगर मुझे तो एक ही सवार नज़र आता है। कर्नल µ (खिड़की के पास जाकर) हाँ, एक ही सवार है। सपाट घोड़ा दौड़ाए चला आ रहा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('d30e4e35-7ef9-4f63-a989-b5ade1c6ecbe', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ़्टिनेंट µ और सीधा हमारी तरफ़ आता मालूम होता है (कर्नल ताली बजाकर सिपाही को बुलाता है) कर्नल µ (सिपाही से) सिपाहियों से कहो, इस सवार पर नज़र रखें कि ये किस तरफ़ जा रहा है (सिपाही सलाम करके चला जाता है) लेफ़्टिनेंट µ शुबहे की तो कोई गुंजाइश ही नहीं तेज़ी से इसी तरफ़ आ रहा है (टापों की आवाज़ बहुत क़रीब आकर रुक जाती है) सवार µ (बाहर से) मुझे कर्नल से मिलना है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('3d4ca4fe-d0ef-4b71-8da3-87b2a55cf4fd', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गोरा µ (चिल्लाकर) बहुत ख़ूब। सवार µ (बाहर से) जी। गोरा µ (अंदर आकर) हुज़ूर सवार आपसे मिलना चाहता है। कर्नल µ भेज दो। लेफ़्टिनेंट µ वज़ीर अली का कोई आदमी होगा हमसे मिलकर उसे गिरफ़्तार करवाना चाहता होगा। कर्नल µ ख़ामोश रहो (सवार सिपाही के साथ अंदर आता है)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('f607d81b-c9f0-4f67-97cb-b9256fc683db', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सवार µ (आते ही पुकार उठता है) तन्हाई! तन्हाई! कर्नल µ साहब यहाँ कोई ग़ैर आदमी नहीं है आप राज़ेदिल कह दें। सवार µ दीवार हमगोश दारद, तन्हाई। (कर्नल, लेफ़्टिनेंट और सिपाही को इशारा करता है। दोनों बाहर चले जाते हैं। जब कर्नल और सवार ख़ेमे में तन्हा रह जाते हैं तो ज़रा वक़्फ़े के बाद चारों तरफ़ देखकर सवार कहता है)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('927f6015-5374-4794-ac41-863f33049584', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वज़ीर अली की स्कीम ये है कि किसी तरह नेपाल पहुँच जाए। अफ़ग़ानी हमले का इंतज़ार करे, अपनी ताक़त बढ़ाए, सआदत अली को उसके पद से हटाकर ख़ुद अवध पर कब्ज़ा करे और अंग्रेज़ों को हिंदुस्तान से निकाल दे। हमारी फ़ौजें और नवाब सआदत अली ख़ाँ के सिपाही बड़ी सख़्ती से उसका पीछा कर रहे हैं। हमें अच्छी तरह मालूम है कि वो इन्हीं जंगलों में है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('cabe6034-d2c1-4e14-9623-1110449a2b87', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दूर से गर्द उठती दिखाई दे रही है। सिपाहियों से कह दो कि तैयार रहें। गर्द तो ऐसी उड़ रही है जैसे कि पूरा एक काफ़िला चला आ रहा हो मगर मुझे तो एक ही सवार नज़र आता है। हाँ, एक ही सवार है। सपाट घोड़ा दौड़ाए चला आ रहा है। और सीधा हमारी तरफ़ आता मालूम होता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('51081496-4be0-44a8-ba34-580630eae9d2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सिपाहियों से कहो, इस सवार पर नज़र रखें कि ये किस तरफ़ जा रहा है। शुबहे की तो कोई गुंजाइश ही नहीं तेज़ी से इसी तरफ़ आ रहा है। टापों की आवाज़ बहुत क़रीब आकर रुक जाती है। मुझे कर्नल से मिलना है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ab79fe07-68d1-49f0-91ef-2ebfd9237ccd', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गोरा µ (चिल्लाकर) बहुत ख़ूब। सवार µ (बाहर से) जी। गोरा µ (अंदर आकर) हुज़ूर सवार आपसे मिलना चाहता है। कर्नल µ भेज दो। लेफ़्टिनेंट µ वज़ीर अली का कोई आदमी होगा हमसे मिलकर उसे गिरफ़्तार करवाना चाहता होगा। कर्नल µ ख़ामोश रहो। सवार सिपाही के साथ अंदर आता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('e700236e-d211-4785-86a5-31c8300a70e7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सवार µ (आते ही पुकार उठता है) तन्हाई! तन्हाई! कर्नल µ साहब यहाँ कोई ग़ैर आदमी नहीं है आप राज़ेदिल कह दें। सवार µ दीवार हमगोश दारद, तन्हाई। कर्नल, लेफ़्टिनेंट और सिपाही को इशारा करता है। दोनों बाहर चले जाते हैं। जब कर्नल और सवार ख़ेमे में तन्हा रह जाते हैं तो ज़रा वक़्फ़े के बाद चारों तरफ़ देखकर सवार कहता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('fc92f456-8c78-4215-93c2-f4b9170d13d7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वज़ीर अली की स्कीम ये है कि किसी तरह नेपाल पहुँच जाए। अफ़ग़ानी हमले का इंतज़ार करे, अपनी ताक़त बढ़ाए, सआदत अली को उसके पद से हटाकर ख़ुद अवध पर कब्ज़ा करे और अंग्रेज़ों को हिंदुस्तान से निकाल दे। लेफ़्टिनेंट µ नेपाल पहुँचना तो कोई ऐसा मुश्किल नहीं, मुमकिन है कि पहुँच गया हो। कर्नल µ हमारी फ़ौजें और नवाब सआदत अली ख़ाँ के सिपाही बड़ी सख़्ती से उसका पीछा कर रहे हैं। हमें अच्छी तरह मालूम है कि वो इन्हीं जंगलों में है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
