  ('b8f6e0a3-6d54-466c-a21e-5c2a5c1bf8fa', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गोरा µ (चिल्लाकर) बहुत ख़ूब। सवार µ (बाहर से) जी। गोरा µ (अंदर आकर) हुज़ूर सवार आपसे मिलना चाहता है। कर्नल µ भेज दो। लेफ़्टिनेंट µ वज़ीर अली का कोई आदमी होगा हमसे मिलकर उसे गिरफ़्तार करवाना चाहता होगा। कर्नल µ ख़ामोश रहो (सवार सिपाही के साथ अंदर आता है)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('2d0a21c0-5198-4239-bf36-32f46a40530b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सवार µ (आते ही पुकार उठता है) तन्हाई! तन्हाई! कर्नल µ साहब यहाँ कोई ग़ैर आदमी नहीं है आप राज़ेदिल कह दें। सवार µ दीवार हमगोश दारद, तन्हाई। (कर्नल, लेफ़्टिनेंट और सिपाही को इशारा करता है। दोनों बाहर चले जाते हैं। जब कर्नल और सवार ख़ेमे में तन्हा रह जाते हैं तो ज़रा वक़्फ़े के बाद चारों तरफ़ देखकर सवार कहता है)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('60b55e3f-6217-4672-af10-307d66b07851', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ़्टिनेंट µ मगर वज़ीर अली की स्कीम क्या है? कर्नल µ स्कीम ये है कि किसी तरह नेपाल पहुँच जाए। अफ़ग़ानी हमले का इंतज़ार करे, अपनी ताक़त बढ़ाए, सआदत अली को उसके पद से हटाकर ख़ुद अवध पर कब्ज़ा करे और अंग्रेज़ों को हिंदुस्तान से निकाल दे। लेफ़्टिनेंट µ नेपाल पहुँचना तो कोई ऐसा मुश्किल नहीं, मुमकिन है कि पहुँच गया हो। कर्नल µ हमारी फ़ौजें और नवाब सआदत अली ख़ाँ के सिपाही बड़ी सख़्ती से उसका पीछा कर रहे हैं। हमें अच्छी तरह मालूम है कि वो इन्हीं जंगलों में है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('aa4e3e5f-8167-4afa-8995-dc79892af515', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कर्नल µ (उठकर) क्या बात है? गोरा µ दूर से गर्द उठती दिखाई दे रही है। कर्नल µ सिपाहियों से कह दो कि तैयार रहें (सिपाही सलाम करके चला जाता है) लेफ़्टिनेंट µ (जो खिड़की से बाहर देखने में मसरूफ़ था) गर्द तो ऐसी उड़ रही है जैसे कि पूरा एक काफ़िला चला आ रहा हो मगर मुझे तो एक ही सवार नज़र आता है। कर्नल µ (खिड़की के पास जाकर) हाँ, एक ही सवार है। सपाट घोड़ा दौड़ाए चला आ रहा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('f88722d4-87d5-4099-b8d8-69d9f72d7cb3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेफ़्टिनेंट µ और सीधा हमारी तरफ़ आता मालूम होता है (कर्नल ताली बजाकर सिपाही को बुलाता है) कर्नल µ (सिपाही से) सिपाहियों से कहो, इस सवार पर नज़र रखें कि ये किस तरफ़ जा रहा है (सिपाही सलाम करके चला जाता है) लेफ़्टिनेंट µ शुबहे की तो कोई गुंजाइश ही नहीं तेज़ी से इसी तरफ़ आ रहा है (टापों की आवाज़ बहुत क़रीब आकर रुक जाती है) सवार µ (बाहर से) मुझे कर्नल से मिलना है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('c640f041-4228-41b5-be4d-aaaefb9d5432', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'fcae70f8-569e-43c6-9ade-6033ee963f71', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गोरा µ (चिल्लाकर) बहुत ख़ूब। सवार µ (बाहर से) जी। गोरा µ (अंदर आकर) हुज़ूर सवार आपसे मिलना चाहता है। कर्नल µ भेज दो। लेफ़्टिनेंट µ वज़ीर अली का कोई आदमी होगा हमसे मिलकर उसे गिरफ़्तार करवाना चाहता होगा। कर्नल µ ख़ामोश रहो (सवार सिपाही के साथ अंदर आता है)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-44-643Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
